def maxProfitShares(prices, m):
    NEG = -10 ** 9
    dp = [0] + [NEG] * m
    for p in prices:
        nd = dp[:]
        for j in range(m + 1):
            if j > 0 and dp[j - 1] - p > nd[j]:
                nd[j] = dp[j - 1] - p
            if j < m and dp[j + 1] + p > nd[j]:
                nd[j] = dp[j + 1] + p
        dp = nd
    return dp[0]
